"}, {"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立白色牢笼的封闭空间，引入沈刻的超忆视角和林白的失忆状态，展示'每日重置'的规则系统。第一幕以林白某天的'第一次醒来'切入，通过沈刻的'重新追求'展示两人的关系机制，最后以林白发现墙上的刻痕作为转折点。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "第1次",
        "core_event": "林白醒来面对空白的一天，沈刻开始他的'第47次追求'，两人在活动室相遇，沈刻用病历本折成的纸飞机引起林白的注意",
        "emotional_tone": "轻柔的绝望，仪式化的温柔",
        "key_scenes": [
          "林白在病房醒来，床头柜上的药瓶和病历本（标注'Day 47'）",
          "沈刻在墙上刻下新的数字，墙上已满是'第X次'的痕迹",
          "活动室的规则：每天下午3点，患者可以自由交流",
          "沈刻用病历本折纸飞机，上面写着他今天编造的'自我介绍'",
          "林白被纸飞机击中，展开后看到一行字：'你相信命中注定吗？'"
        ]
      }
    ],
    "turning_point": "林白在活动室的角落里发现一面被窗帘遮住的墙，上面密密麻麻刻满了'今天她笑了几次'，以及她每天说过的每一句话。她意识到这个'第一次'不是第一次。"
  },
  "act_two": {
    "description": "冲突螺旋升级：林白开始'保留记忆'（或假装失忆），在知情的状态下与沈刻互动，观察他的'表演'。沈刻逐渐察觉林白的变化，两人的关系从'每日重置的纯粹'变成'清醒的共谋'。中点转折是林白发现实验真相——他们不是在治疗，而是被观察的实验品。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "第48次",
        "core_event": "林白假装失忆配合沈刻的'追求'，同时偷偷在陈教授办公室寻找线索，发现'配对治疗'的真实性质",
        "emotional_tone": "甜蜜的虚伪，暗流涌动",
        "key_scenes": [
          "林白醒来，发现床头柜的病历本写着'Day 48'，但她记得昨天",
          "沈刻的'追求'脚本：早餐的糖果、走廊的'偶遇'、活动室的话题",
          "林白假装第一次听到这些，却在心里计数：这是他第几次说'你的眼睛像我认识的一个人'",
          "深夜，林白潜入医生办公室，看到实验档案：《超忆-失忆配对模型的情感依赖性研究》",
          "档案中的照片：她和沈刻在入院前的街角，两人曾擦肩而过"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "第49次",
        "core_event": "沈刻察觉林白的'不一致'，两人在药瓶 ritual 中爆发第一次真诚对话，沈刻承认'我记得所有事'，林白承认'我也记得'",
        "emotional_tone": "真相揭露的震颤，病态的坦诚",
        "key_scenes": [
          "服药时间的规则：每天必须当着护士的面服药，但沈刻学会把药片藏在舌底",
          "林白也开始藏药，两人在洗手间相遇，吐出同样的白色药片",
          "沈刻带林白去看那面墙，上面除了'她笑了几次'，还有'她说谎了几次'、'她藏药了几次'",
          "林白问：'你为什么要记录这些？'沈刻答：'因为这是我拥有的全部'",
          "林白发现沈刻在墙的最下方刻着：'第1次，她看了我一眼'——那是入院前的往事"
        ]
      }
    ],
    "turning_point": "陈教授发现两人在藏药并私下接触，决定'升级'实验——他告诉林白：沈刻的躁狂症是装的，他入院就是为了接近她，而她真正的创伤记忆被实验性药物压制了。林白面临选择：继续服药失忆，或停药面对真相。"
  },
  "act_three": {
    "description": "高潮对决：林白选择停药，记忆如洪水般涌回——她曾在自杀边缘被沈刻救下，但那段记忆太过痛苦被她主动遗忘。沈刻的超忆症让他背负了所有的记忆，包括那个血腥的夜晚。最终两人面对极限二选一：出院获得自由但失去彼此，或留在医院继续这场'纯粹的疯狂'。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "第50次（最后一次）",
        "core_event": "林白停药后恢复全部记忆，回忆起她与沈刻的真正相识——他在她跳楼时抓住了她的手，而她选择遗忘这段创伤。两人面对陈教授的'毕业测试'",
        "emotional_tone": "记忆重载的痛苦，真相的灼伤",
        "key_scenes": [
          "林白停药后连续三天无法入睡，记忆如潮水涌来：跳楼的天台、抓住她的手、医院的白墙",
          "她终于明白，沈刻不是实验的受害者，而是为了接近她才自愿入院的患者",
          "陈教授给出选择：'你们已经可以出院了，实验数据显示配对治疗有效'",
          "沈刻对林白说：'你可以走，不用记得我。我习惯了记住所有事，包括被遗忘'",
          "林白看向那面墙，最后一次数了'她笑了几次'——总共是127次"
        ]
      },
      {
        "chapter_number": 5,
        "chapter_title": "第51次（自愿的）",
        "core_event": "林白选择留在医院，继续服用失忆药物，但要求沈刻继续'追求'她。两人达成病态的共识：只有疯子的爱情才纯粹。结尾以林白在墙上添加新的刻痕作为封蜡",
        "emotional_tone": "觉醒后的自愿沉溺，悲剧性的圆满",
        "key_scenes": [
          "出院签字表前，林白把笔放下，走向药房",
          "她对陈教授说：'实验还没结束，我想继续治疗'",
          "沈刻在活动室等到下午3点，林白如约出现，眼神又是全新的陌生",
          "但他注意到，她的嘴角带着一丝只有他记得的笑意",
          "晚上，林白在被窗帘遮住的墙上，用护士小周给的笔，刻下一行新字：'第51次，我决定不逃'",
          "最后一句：药瓶在床头柜上，两个白色药片静静躺着，像一对约定的戒指"
        ]
      }
    ],
    "turning_point": "林白在墙上刻下'我决定不逃'，标志着从'被动失忆者'到'自愿沉溺者'的转变，完成D22'为激情牺牲一切'的最终显影——她牺牲了记忆自由和外部世界的真实，换取每日重置的纯粹爱意。"
  }
}
"}]}

